function Upgrades:StartScan()
    if not self:IsEnabledForCharacter() or (InCombatLockdown and InCombatLockdown()) then return end
    if UnitIsDeadOrGhost and UnitIsDeadOrGhost("player") then return end
    local signature, scale = EquipmentSignature(), self:GetScale()
    if not signature or not scale then return end
    self.dismissed = self.dismissed or {}
    self.job = { bag = 0, slot = 0, signature = signature, scale = scale, candidates = {}, pending = {} }
    self:ScanBatch()
end--[[APR_DIAG]]
Upgrades.StartScan = APRTrace("APR-Core/features/player/BagUpgrades.lua:85:Upgrades:StartScan#13", Upgrades.StartScan)--[[/APR_DIAG]]

function Upgrades:ScanBatch()
    local job, generation = self.job, self.generation
    if not job or not self:IsEnabledForCharacter() then return end
    -- Eight slots per slice bounds scoring work and lets bag/equipment events cancel stale scans.
    for _ = 1, 8 do
        local count = Container("GetContainerNumSlots", job.bag)
        if not Number(count) or count < 0 then
            self.job = nil
            return
        end
        job.slot = job.slot + 1
        while job.slot > count do
            job.bag, job.slot = job.bag + 1, 1
            if job.bag > (NUM_BAG_SLOTS or 4) then
                self:FinishScan(job)
                return
            end
            count = Container("GetContainerNumSlots", job.bag)
            if not Number(count) or count < 0 then
                self.job = nil
                return
            end
        end
        local link = Container("GetContainerItemLink", job.bag, job.slot)
        if Public(link) and type(link) == "string" and self.dismissed[link] ~= job.signature then
            local gain, ready, plan = APR.RewardScoring:GetUpgrade(link, job.scale)
            if not ready then
                local id = tonumber(link:match("item:(%d+)"))
                if id then job.pending[id] = true end
            elseif Number(gain) and gain > 0 and plan then
                job.candidates[#job.candidates + 1] = {
                    link = link,
                    gain = gain,
                    plan = plan,
                    bag = job.bag,
                    slot = job.slot,
                    signature = job.signature,
                }
            end
        end
    end
    self.timer = C_Timer.NewTimer(
        0, --[[APR_DIAG]]
        APRTrace("APR-Core/features/player/BagUpgrades.lua:121:callback#15", --[[/APR_DIAG]] function()
            self.timer = nil
            if self.generation == generation and self.job == job then self:ScanBatch() end
        end--[[APR_DIAG]]) --[[/APR_DIAG]]
    )
end--[[APR_DIAG]]
Upgrades.ScanBatch = APRTrace("APR-Core/features/player/BagUpgrades.lua:95:Upgrades:ScanBatch#14", Upgrades.ScanBatch)--[[/APR_DIAG]]

function Upgrades:FinishScan(job)
    local generation = self.generation
    self.job = nil
    if EquipmentSignature() ~= job.signature then
        self:QueueScan()
        return
    end
    -- Request each missing item at most twice between inventory/scoring changes.
    -- Some unusable/opaque items never produce a score; they must not loop forever
    -- or prevent independently loaded upgrades from being offered.
    if next(job.pending) then
        for id in job.signature:gmatch("item:(%d+)") do
            job.pending[tonumber(id)] = true
        end
        self.requests = self.requests or {}
        local pending = {}
        for id in pairs(job.pending) do
            if (self.requests[id] or 0) < 2 then
                self.requests[id] = (self.requests[id] or 0) + 1
                pending[id] = true
            end
        end
        self.pendingIDs = pending
        self:RegisterEvent("ITEM_DATA_LOAD_RESULT", "OnItemData")
        for id in pairs(pending) do
            if C_Item and C_Item.RequestLoadItemDataByID then C_Item.RequestLoadItemDataByID(id) end
        end
        if self.generation ~= generation then return end
        if next(pending) then
            -- A failed/missing item event also has a bounded recovery path.
            local tmpGeneration = self.generation
            self.timer = C_Timer.NewTimer(
                1, --[[APR_DIAG]]
                APRTrace("APR-Core/features/player/BagUpgrades.lua:150:callback#17", --[[/APR_DIAG]] function()
                    self.timer = nil
                    if self.generation == tmpGeneration then self:QueueScan() end
                end--[[APR_DIAG]]) --[[/APR_DIAG]]
            )
            return
        end
        self:UnregisterEvent("ITEM_DATA_LOAD_RESULT")
        self.pendingIDs = nil
    end
    table.sort(
        job.candidates, --[[APR_DIAG]]
        APRTrace("APR-Core/features/player/BagUpgrades.lua:159:callback#18", --[[/APR_DIAG]] function(a, b)
            if a.gain ~= b.gain then return a.gain > b.gain end
            if a.bag ~= b.bag then return a.bag < b.bag end
            return a.slot < b.slot
        end--[[APR_DIAG]]) --[[/APR_DIAG]]
    )
    if job.candidates[1] then self:Offer(job.candidates[1]) end
end--[[APR_DIAG]]
Upgrades.FinishScan =
    APRTrace("APR-Core/features/player/BagUpgrades.lua:127:Upgrades:FinishScan#16", Upgrades.FinishScan)--[[/APR_DIAG]]

function Upgrades:Equip(candidate)
    if not self:IsEnabledForCharacter() or (InCombatLockdown and InCombatLockdown()) then return end
    if CursorHasItem and CursorHasItem() then return end
    if EquipmentSignature() ~= candidate.signature then
        self:QueueScan()
        return
    end
    local link = Container("GetContainerItemLink", candidate.bag, candidate.slot)
    if not Public(link) or link ~= candidate.link then
        self:QueueScan()
        return
    end
    local infoAPI = C_Container and C_Container.GetContainerItemInfo
    if infoAPI then
        local info = infoAPI(candidate.bag, candidate.slot)
        if
            not Public(info)
            or type(info) ~= "table"
            or (canaccesstable and not canaccesstable(info))
            or not Public(info.isLocked)
            or info.isLocked ~= false
        then
            return
        end
    end
    local gain, ready, plan = APR.RewardScoring:GetUpgrade(link, self:GetScale())
    local equip = C_Item and C_Item.EquipItemByName or EquipItemByName
    if not ready or not Number(gain) or gain <= 0 or not plan or not equip then
        self:QueueScan()
        return
    end
    if plan.move then
        if GetInventoryItemLink("player", plan.move.from) ~= plan.move.link then
            self:QueueScan()
            return
        end
        equip(plan.move.link, plan.move.to)
        -- Never schedule a protected inventory action for a later timer/event.
        if GetInventoryItemLink("player", plan.move.to) ~= plan.move.link then
            self:QueueScan()
            return
        end
    end
    equip(link, plan.slot)
    self:QueueScan()
end--[[APR_DIAG]]
Upgrades.Equip = APRTrace("APR-Core/features/player/BagUpgrades.lua:167:Upgrades:Equip#19", Upgrades.Equip)--[[/APR_DIAG]]

function Upgrades:Offer(candidate)
    if not self:IsEnabledForCharacter() or (InCombatLockdown and InCombatLockdown()) then return end
    -- Use the private dialog even in mouse mode on a gamepad-capable client:
    -- switching input modes while an offer is open must not adopt a StaticPopup.
    local private = APR.Gamepad and APR.Gamepad.IsAvailable and APR.Gamepad:IsAvailable()
    if private then
        if not APR.UI or not APR.UI.ShowConfirmationDialog then return end
    elseif not APR.questionDialog or not StaticPopup_Visible then
        return
    end
    for index = 1, (STATICPOPUP_NUMDIALOGS or 4) do
        local frame = _G["StaticPopup" .. index]
        if frame and frame:IsShown() then
            self.waiting = true
            return
        end
    end
    self.prompt, self.waiting = candidate, nil
    local current = {}
    for _, slot in ipairs(candidate.plan.replacedSlots) do
        local link = GetInventoryItemLink("player", slot)
        if link then current[#current + 1] = link end
    end
    local text = L["CHOOSE_USABLE_GEAR_UPGRADE"]
        .. "\n\n"
        .. candidate.link
        .. "\n"
        .. (CURRENTLY_EQUIPPED or EQUIPMENT)
        .. ": "
        .. (#current > 0 and table.concat(current, "\n") or EMPTY or NONE or "")
    local onAccept = --[[APR_DIAG]]
        APRTrace("APR-Core/features/player/BagUpgrades.lua:204:callback#21", --[[/APR_DIAG]] function()
            if self.prompt ~= candidate then return end
            self.prompt, self.dialog = nil, nil
            self:Equip(candidate)
        end--[[APR_DIAG]]) --[[/APR_DIAG]]
    local onCancel = --[[APR_DIAG]]
        APRTrace("APR-Core/features/player/BagUpgrades.lua:208:callback#22", --[[/APR_DIAG]] function(_, _, reason)
            if self.prompt ~= candidate then return end
            self.prompt, self.dialog = nil, nil
            local dismissed = private or reason == "clicked" or reason == "timeout" or reason == "escape"
            if dismissed then self.dismissed[candidate.link] = candidate.signature end
            self.waiting = not dismissed
            if not self.waiting then self:QueueScan() end
        end--[[APR_DIAG]]) --[[/APR_DIAG]]
    if private then
        -- Forever initializes native StaticPopup gamepad callbacks in the
        -- caller's taint context and lazily caches their shared bindings there.
        -- Keep this offer on an APR-owned frame instead of entering that path.
        self.dialog = APR.UI:ShowConfirmationDialog({
            dialogName = "APRBagUpgradePopup",
            title = EQUIPMENT,
            description = text,
            acceptText = EQUIP_ITEM or EQUIP or ACCEPT,
            cancelText = IGNORE or CANCEL,
        }, onAccept, onCancel)
    else
        APR.questionDialog:CreateQuestionPopup(
            PROMPT, text, onAccept, onCancel, EQUIP_ITEM or EQUIP or ACCEPT, IGNORE or CANCEL
        )
    end
    if (private and (not self.dialog or not self.dialog:IsShown())) or (not private and not StaticPopup_Visible(PROMPT)) then
        self.prompt, self.waiting = nil, true
    end
end--[[APR_DIAG]]
Upgrades.Offer = APRTrace("APR-Core/features/player/BagUpgrades.lua:189:Upgrades:Offer#20", Upgrades.Offer)--[[/APR_DIAG]]

function Upgrades:RefreshSettings()
    self:CancelScan()
    self:CancelPrompt()
    self:UnregisterAllEvents()
    if not self:IsEnabledForCharacter() then return end
    for _, event in ipairs(EVENTS) do
        self:RegisterEvent(event, "QueueScan")
    end
    self:QueueScan()
end--[[APR_DIAG]]
